// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref, uint256 seedAmount) public {
        vm.assume(caller != address(0) && ref != address(0) && caller != ref);
        vm.assume(seedAmount >= 1e15 && seedAmount <= 1e18);

        // Seed the market and give caller some kilos
        c.seedMarket{value: 1e18}(86400);
        vm.deal(caller, 1e18);
        vm.prank(caller);
        c.getFreeKilo();

        // Let some time pass so caller accumulates drugs
        vm.warp(block.timestamp + 86401);

        // Record claimedDrugs of ref before collectDrugs
        uint256 refClaimedBefore = c.claimedDrugs(ref);

        // Caller collects drugs with ref
        vm.prank(caller);
        c.collectDrugs(ref);

        // Check that ref's claimedDrugs increased (in reference, ref gets 1/5 of drugsUsed)
        uint256 refClaimedAfter = c.claimedDrugs(ref);
        assertTrue(refClaimedAfter > refClaimedBefore, "Referral should receive drugs");
    }
}

